import React, { createContext, useContext, useState, useEffect } from 'react';
import { auth } from '../firebase/config'; // Importă obiectul de autentificare din config.js
import { onAuthStateChanged } from 'firebase/auth';

// 1. Creează Context-ul
const AuthContext = createContext();

// 2. Creează Provider-ul (componenta care încapsulează App.js)
export const AuthProvider = ({ children }) => {
    const [user, setUser] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // onAuthStateChanged ascultă modificările stării de login de la Firebase
        const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
            setUser(currentUser);
            setLoading(false);
        });

        // Cleanup la demontare
        return () => unsubscribe();
    }, []);

    // Obiectul cu datele și funcțiile care vor fi disponibile în toată aplicația
    const value = {
        user,
        loading,
        // Aici vom adăuga funcțiile de login/register în Pasul 4
    };

    return (
        <AuthContext.Provider value={value}>
            {!loading && children}
        </AuthContext.Provider>
    );
};

// 3. Creează Hook-ul Custom pentru utilizare ușoară
export const useAuth = () => {
    return useContext(AuthContext);
};
